/* From Uiverse.io by aadium - Tags: material design, login, card */
.__UIV_SCOPE__ .login-card {
  width: 250px;
  height: 240px;
  background-color: #f2f2f2;
  border-radius: 25px;
  box-shadow: 2px 2px 15px rgb(193, 193, 193);
}

.__UIV_SCOPE__ .instruction-text {
  color: rgb(150, 150, 150);
  text-align: center;
  font-size: 12px;
  margin-top: 10px;
  margin-bottom: px;
}

.__UIV_SCOPE__ .login-card button {
  cursor: pointer;
}

.__UIV_SCOPE__ .normal-signin {
  padding: 10px;
  font-size: 17px;
  width: 70%;
  margin-top: 25px;
  margin-left: 37px;
  border: 2px solid transparent;
  border-radius: 5em;
  background-color: #1b77da;
  color: #f2f2f2;
  font-weight: bold;
  font-family: sans-serif;
  transition: 0.2s;
}

.__UIV_SCOPE__ .normal-signin:hover {
  background-color: transparent;
  color: #1b77da;
  border: 2px solid #1b77da;
}

.__UIV_SCOPE__ .create-account {
  padding: 10px;
  font-size: 17px;
  width: 70%;
  margin-top: 5px;
  margin-left: 37px;
  margin-bottom: 5px;
  border: 2px solid transparent;
  border-radius: 5em;
  background-color: #e8e8e8;
  color: #1b77da;
  font-weight: bold;
  font-family: sans-serif;
  transition: 0.2s;
}

.__UIV_SCOPE__ .create-account:hover {
  background-color: transparent;
  color: #1b77da;
  border: 2px solid #1b77da;
}

.__UIV_SCOPE__ .alternate-login {
  margin-left: 42px;
  margin-top: 5px;
  background-color: #f2f2f2;
  border-radius: 5em;
}

.__UIV_SCOPE__ .m-sign {
  padding: 7px;
  font-size: 14px;
  height: 40px;
  width: 40px;
  border-radius: 5em;
  margin-top: 5px;
  background-color: #7FBA00;
  border: 2px solid transparent;
  transition: 0.2s;
}

.__UIV_SCOPE__ .m-sign svg {
  width: 27px;
  height: 27px;
  margin-top: -2px;
  margin-left: -2px;
  fill: #f2f2f2;
}

.__UIV_SCOPE__ .m-sign:hover {
  background-color: transparent;
  border: 2px solid #7FBA00;
}

.__UIV_SCOPE__ .m-sign:hover svg {
  fill: #7FBA00;
}

.__UIV_SCOPE__ .g-sign {
  padding: 7px;
  font-size: 14px;
  height: 40px;
  width: 40px;
  border-radius: 5em;
  margin-top: 5px;
  margin-left: 15px;
  background-color: #DB4437;
  border: 2px solid transparent;
  transition: 0.2s;
}

.__UIV_SCOPE__ .g-sign svg {
  width: 23px;
  height: 25px;
  margin-top: -1.5px;
  fill: #f2f2f2;
}

.__UIV_SCOPE__ .g-sign:hover {
  background-color: transparent;
  border: 2px solid #DB4437;
}

.__UIV_SCOPE__ .g-sign:hover svg {
  fill: #DB4437;
}

.__UIV_SCOPE__ .a-sign {
  padding: 7px;
  font-size: 14px;
  height: 40px;
  width: 40px;
  border-radius: 5em;
  margin-top: 5px;
  margin-left: 15px;
  background-color: #000000;
  border: 2px solid transparent;
  transition: 0.2s;
}

.__UIV_SCOPE__ .a-sign svg {
  width: 25px;
  height: 25px;
  margin-top: -1px;
  margin-left: -1px;
  fill: #f2f2f2;
}

.__UIV_SCOPE__ .a-sign:hover {
  background-color: transparent;
  border: 2px solid #000000;
}

.__UIV_SCOPE__ .a-sign:hover svg {
  fill: #000000;
}
